import{_ as e,o as l,c as a,ah as d}from"./chunks/framework.Bv6G8Ib6.js";const i="/arch-guidelines/assets/harvard_map.BEzCJeaF.svg",n="/arch-guidelines/assets/axis_tree.DT06zu47.svg",s="/arch-guidelines/assets/appendix_axis_route.CgMbCaDd.svg",r="/arch-guidelines/assets/mitigation_flow.vkKqIGMC.svg",b=JSON.parse('{"title":"Appendix","description":"","frontmatter":{"sidebarDepth":4,"title":"Appendix","author":"フューチャー株式会社","search":false,"head":[["meta",{"name":"robots","content":"noindex, nofollow"}]]},"headers":[],"relativePath":"documents/forSoftSkill/consensus/appendix.md","filePath":"documents/forSoftSkill/consensus/appendix.md"}'),x={name:"documents/forSoftSkill/consensus/appendix.md"};function f(g,t,h,o,y,p){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h1><h2 id="合意形成の手続き" tabindex="-1">合意形成の手続き <a class="header-anchor" href="#合意形成の手続き" aria-label="Permalink to &quot;合意形成の手続き&quot;">​</a></h2><h3 id="一般的な合意形成術との関係" tabindex="-1">一般的な合意形成術との関係 <a class="header-anchor" href="#一般的な合意形成術との関係" aria-label="Permalink to &quot;一般的な合意形成術との関係&quot;">​</a></h3><p>本書の手続きは、ハーバード流交渉術の4原則を概ね踏襲し、技術を相手の言葉に翻訳する手続きを追加している。 <img src="'+i+'" alt="一般的な合意形成術との関係" width="1560" height="438"></p><h2 id="手続き4-各案を観点ごとに評価する" tabindex="-1">手続き4 各案を観点ごとに評価する <a class="header-anchor" href="#手続き4-各案を観点ごとに評価する" aria-label="Permalink to &quot;手続き4 各案を観点ごとに評価する&quot;">​</a></h2><h3 id="案の絞り込みパターン" tabindex="-1">案の絞り込みパターン <a class="header-anchor" href="#案の絞り込みパターン" aria-label="Permalink to &quot;案の絞り込みパターン&quot;">​</a></h3><p>洗い出した案を絞り込む理由は、制約、要件の未達、劣位に3分類できる。</p><table tabindex="0"><thead><tr><th style="text-align:left;">分類</th><th style="text-align:left;">パターン</th><th style="text-align:left;">説明</th><th style="text-align:left;">絞り込む場合の相手への伝え方の例</th></tr></thead><tbody><tr><td style="text-align:left;">制約</td><td style="text-align:left;">技術制約</td><td style="text-align:left;">相手の既存環境に載らないもの、既存システムとつながらないもの、自分たちの技術方針（サポート終了が近い製品は採らない、など）に反するものを外す</td><td style="text-align:left;">「今の閉域網でつながるのは AWS だけなので、ほかのクラウドは外します」</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">ビジネス制約</td><td style="text-align:left;">IT 方針、法規制、契約に反するものを外す</td><td style="text-align:left;">「業界のガイドラインでデータを国内で保管する必要があるため、国内リージョンのない製品は外します」</td></tr><tr><td style="text-align:left;">要件の未達</td><td style="text-align:left;">機能要件</td><td style="text-align:left;">今回の用途に要る機能（データ基盤なら、アクセス権限の管理やデータカタログ）を持たないものを外す</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">非機能要件 （性能・拡張性）</td><td style="text-align:left;">今のデータ量や利用者数で基準を満たさないものと、増えたときに持ちこたえないものを外す</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">非機能要件 （移植性）</td><td style="text-align:left;">用途が固まらない段階で、特定の技術にロックインされ、後から載せ替えにくいものを外す</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">非機能要件 （保守性）</td><td style="text-align:left;">標準的な運用プロセスに乗らないもの、作り込みが要るもの、扱える人を確保しにくいものを外す</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">劣位</td><td style="text-align:left;">下位互換</td><td style="text-align:left;">どの観点でも、ほかの候補と同等か劣るものを選択肢から外す</td><td style="text-align:left;"></td></tr></tbody></table><h2 id="手続き5-相手が判断できる評価軸に組み替える" tabindex="-1">手続き5 相手が判断できる評価軸に組み替える <a class="header-anchor" href="#手続き5-相手が判断できる評価軸に組み替える" aria-label="Permalink to &quot;手続き5 相手が判断できる評価軸に組み替える&quot;">​</a></h2><h3 id="評価軸に借りる既成の軸" tabindex="-1">評価軸に借りる既成の軸 <a class="header-anchor" href="#評価軸に借りる既成の軸" aria-label="Permalink to &quot;評価軸に借りる既成の軸&quot;">​</a></h3><p>システム構築のプロジェクトでは、大分類に QCD を借りると収まりがよい。Q の中身は ISO/IEC 25010 の品質特性を参考にできる。広く受け入れられた分類を起点にすれば、「なぜこの軸なのか」と問われにくく、観点の抜けも防げる。</p><p><img src="'+n+'" alt="評価軸に借りる既成の軸" width="1348" height="700" loading="lazy"></p><p>攻め・守りを大分類にするときは、性能や開発の速さを攻めの側、セキュリティや可用性を守りの側に振り分ける。相手が攻めと守りのどちらを重視するかで判断しようとしているときに使う。どの軸を借りるかは、相手に何を問いたいかで選ぶ。</p><h2 id="手続き6-評価軸からコンセプト別の選択肢を作る" tabindex="-1">手続き6 評価軸からコンセプト別の選択肢を作る <a class="header-anchor" href="#手続き6-評価軸からコンセプト別の選択肢を作る" aria-label="Permalink to &quot;手続き6 評価軸からコンセプト別の選択肢を作る&quot;">​</a></h2><h3 id="相手へのコミュニケーションは、5形式に分類できる" tabindex="-1">相手へのコミュニケーションは、5形式に分類できる <a class="header-anchor" href="#相手へのコミュニケーションは、5形式に分類できる" aria-label="Permalink to &quot;相手へのコミュニケーションは、5形式に分類できる&quot;">​</a></h3><p>比較表の観点は、制約と評価に分かれる。同じセキュリティ項目でも、必須なら制約、充実度を比べるなら評価である。</p><p><img src="'+s+'" alt="観点の分解と行き先" width="1200" height="884" loading="lazy"></p><p>形式ごとに、資料に必要な記載内容が異なる。</p><table tabindex="0"><thead><tr><th style="text-align:left;">区分</th><th style="text-align:left;">形式</th><th style="text-align:left;">相手に求めること</th><th style="text-align:left;">利用条件</th><th style="text-align:left;">資料に必要な記載内容</th></tr></thead><tbody><tr><td style="text-align:left;">相手の価値判断が不要</td><td style="text-align:left;">報告</td><td style="text-align:left;">決めた内容を把握してもらう</td><td style="text-align:left;">相手の価値判断は要らない。自分たちで決めた</td><td style="text-align:left;">決めた内容と、その役割・採用理由、相手側の作業や運用への影響の有無</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">確認</td><td style="text-align:left;">想定が合っているかの確認</td><td style="text-align:left;">相手から事実として回答がある。または別の場ですでに決まっている</td><td style="text-align:left;">自分たちの想定と、その根拠</td></tr><tr><td style="text-align:left;">相手の価値判断が要る / 相談</td><td style="text-align:left;">基準への同意</td><td style="text-align:left;">案を落とす条件や、振り分ける条件に同意を得る。結果は条件から決まり、相手は何も諦めない</td><td style="text-align:left;">候補が多く予選が要る。または、個別の判断をルールで束ねる</td><td style="text-align:left;">基準と、それを適用した結果 （→手続き4-1）</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">優先度の選択</td><td style="text-align:left;">残った案のトレードオフのうち、何を優先し何を諦めるかを、推奨案を添えて合意する</td><td style="text-align:left;">トレードオフの構造が出ていて、案ごとにどの重み付けなら選ぶかが言える。</td><td style="text-align:left;">推奨案と、コンセプト名を付けた案ごとのメリット・デメリット（→手続き6-3、手続き6-4）</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">弱みの許容</td><td style="text-align:left;">推奨案に残る弱みを、緩和策込みで許容できるか確認する</td><td style="text-align:left;">推奨案が1つに絞れていて、弱みが許容できる範囲に収まっている</td><td style="text-align:left;">弱みと緩和策の対 （→手続き8）</td></tr></tbody></table><p>比較表の行が多くても、相手に判断を求めるのは論点に残った数行だけで、残りは報告か確認としてまとめて済ませる。</p><p>報告のうち、打合せで伝える価値が高いのは、一択になった理由が相手側の前提によるもの（海外拠点がないからデータは国内保持、など）、相手のその後の業務や運用に影響するもの、後から覆せないものの3つである。それ以外は資料の補足や文書での報告にとどめてよい。</p><h3 id="コンセプト別の選択肢のパターン" tabindex="-1">コンセプト別の選択肢のパターン <a class="header-anchor" href="#コンセプト別の選択肢のパターン" aria-label="Permalink to &quot;コンセプト別の選択肢のパターン&quot;">​</a></h3><p>評価軸のうち、片方を取るともう片方を諦めることになる組が、コンセプトの対になる。</p><table tabindex="0"><thead><tr><th style="text-align:left;">分類</th><th style="text-align:left;">メリット</th><th style="text-align:left;">デメリット</th><th style="text-align:left;">題材の例</th></tr></thead><tbody><tr><td style="text-align:left;">性能とコスト</td><td style="text-align:left;">応答が速く、操作の体感がよい</td><td style="text-align:left;">年間のコストが上がる</td><td style="text-align:left;">リージョン、インスタンス</td></tr><tr><td style="text-align:left;">スピードと将来の拡張性</td><td style="text-align:left;">すぐ使い始められる</td><td style="text-align:left;">後で載せ替えることになる</td><td style="text-align:left;">PoC 先行の基盤</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">スモールスタートできる</td><td style="text-align:left;">大規模になったときに複雑化しやすい</td><td style="text-align:left;">サーバーレス、小さく始める構成</td></tr><tr><td style="text-align:left;">統制と自由度</td><td style="text-align:left;">全社の統制と調達に乗る</td><td style="text-align:left;">現場の開発生産性が下がる</td><td style="text-align:left;">クラウド、開発ツール</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">自社で統制できる</td><td style="text-align:left;">手離れが悪い</td><td style="text-align:left;">マネージドかセルフか</td></tr><tr><td style="text-align:left;">安心感と先進性</td><td style="text-align:left;">事例が多く失敗しにくい</td><td style="text-align:left;">設計思想が古いまま残る</td><td style="text-align:left;">製品、アーキテクチャ</td></tr><tr><td style="text-align:left;">汎用品と特注品</td><td style="text-align:left;">採用しやすく、外注先も見つかる</td><td style="text-align:left;">特定領域（データ、AI）の立ち上げが遅い</td><td style="text-align:left;">クラウドの選定</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">自前で組むので要件に合わせられる</td><td style="text-align:left;">内製化して運用できる人が要る</td><td style="text-align:left;">フレームワーク、OSS</td></tr></tbody></table><h2 id="手続き8-相手の反応を引き出し合意する" tabindex="-1">手続き8 相手の反応を引き出し合意する <a class="header-anchor" href="#手続き8-相手の反応を引き出し合意する" aria-label="Permalink to &quot;手続き8 相手の反応を引き出し合意する&quot;">​</a></h2><h3 id="緩和策は、4つの型から考える" tabindex="-1">緩和策は、4つの型から考える <a class="header-anchor" href="#緩和策は、4つの型から考える" aria-label="Permalink to &quot;緩和策は、4つの型から考える&quot;">​</a></h3><p>相手が弱みを許容できないときも、別の型の緩和策なら許容できることがある。</p><p><img src="'+r+'" alt="緩和策の4つの型の決定フロー" width="1560" height="788" loading="lazy"></p>',28)])])}const u=e(x,[["render",f]]);export{b as __pageData,u as default};
